const qj = v => q(JSON.stringify(v === undefined ? null : v)) + '::jsonb';
const e164 = v => {
  const d = String(v || '').replace(/\D/g, '');
  if (d.length === 10) return '+1' + d;
  if (d.length === 11 && d[0] === '1') return '+' + d;
  return null;
